WITH gate AS (
  SELECT EXISTS (SELECT 1 FROM content_approvals WHERE job_id=NULLIF('{{$json.job_id}}','')::uuid AND approval_stage='plan' AND decision='approved') AS allowed
), job_update AS (
  UPDATE content_jobs SET status='generating_outputs', updated_at=now()
  WHERE id=NULLIF('{{$json.job_id}}','')::uuid AND (SELECT allowed FROM gate)
  RETURNING id
)
SELECT (SELECT allowed FROM gate) AS allowed, '{{$json.job_id}}' AS job_id, '{{$json.mode}}' AS mode, ('{{$json.mode}}'='live') AS live_mode;

