const state = $node['Normalize And Auth'].json;
if (state.skipped_tool) {
  return [{json: state}];
}
const rawText = $json.choices?.[0]?.message?.content ?? $json.body?.choices?.[0]?.message?.content ?? $json.data?.choices?.[0]?.message?.content ?? '';
let parsed;
let parseWarning = false;
let warningMessage = '';
if (state.mode === 'dry_run' && !rawText) {
  parsed = state.generated_output || state.fallback_payload || {mode: 'dry_run', output_type: state.output_type, items: []};
} else {
  try {
    parsed = typeof rawText === 'string' ? JSON.parse(rawText) : rawText;
  } catch (error) {
    parseWarning = true;
    warningMessage = error.message;
    parsed = {raw_text: rawText, parse_warning: true, output_type: state.output_type};
  }
}
const outputJson = JSON.stringify(parsed || {});
const safeSql = value => String(value ?? '').replace(/'/g, "''");
return [{json: {...state, generated_output: parsed, generated_output_json: outputJson, generated_output_json_sql: safeSql(outputJson), raw_model_text: rawText, raw_model_text_sql: safeSql(rawText), parse_warning: parseWarning, warning_message: warningMessage, warning_message_sql: safeSql(warningMessage), current_stage_sql: safeSql(state.current_stage), output_type_sql: safeSql(state.output_type), dispatch_label_sql: safeSql(state.dispatch_label), qa_status: 'pending'}}];

